window.TASK_BANKS[60] = {"version":1,"topicId":60,"tasks":[{"id":"60.1","codeLang":"python","answer":"1\n[2, 0, 4]","answerLang":"text","explanation":"Figure содержит Axes, а plot создаёт Line2D. Нулевая точка остаётся частью ряда. Agg позволяет сохранить изображение без GUI; программа не должна ждать закрытия окна show().","verified":"3.14","wrong":["3\n[2, 4]","1\n[2, 4]"]},{"id":"60.2","codeLang":"python","answer":"import matplotlib\nmatplotlib.use('Agg')\nimport matplotlib.pyplot as plt\ndef line_chart(xs,ys):\n    fig,ax=plt.subplots(figsize=(4,3))\n    ax.plot(xs,ys,marker='o',label='Наблюдения')\n    ax.set(title='Динамика',xlabel='День',ylabel='Количество')\n    ax.legend()\n    fig.tight_layout()\n    return fig","answerLang":"python","explanation":"Объектная модель позволяет явно вернуть фигуру вызывающему коду. Подпись ряда связывает легенду с данными, подписи осей объясняют величины. Сохранение и закрытие — отдельные действия владельца Figure.","verified":"3.14","check":{"append":"import matplotlib\nmatplotlib.use('Agg')\nimport matplotlib.pyplot as _plt\nimport numpy as _np\nfrom matplotlib.figure import Figure as _Figure\n\nfor xs,ys in [([2,0,1],[5,0,3]),([],[]),([0],[0])]:\n    before=(xs.copy(),ys.copy());fig=line_chart(xs,ys)\n    assert isinstance(fig,_Figure) and len(fig.axes)==1\n    ax=fig.axes[0];assert len(ax.lines)==1\n    series=ax.lines[0]\n    assert _np.array_equal(series.get_xdata(),xs) and _np.array_equal(series.get_ydata(),ys)\n    assert series.get_marker()=='o' and series.get_label()=='Наблюдения'\n    assert ax.get_title()=='Динамика' and ax.get_xlabel()=='День' and ax.get_ylabel()=='Количество'\n    assert ax.get_legend() is not None and [text.get_text() for text in ax.get_legend().texts]==['Наблюдения']\n    assert (xs,ys)==before;_plt.close(fig)\nprint('OK')","expect":"OK"}},{"id":"60.3","codeLang":"python","answer":"[2, 0, 1]\n0","answerLang":"text","explanation":"plot сохраняет порядок X, а не сортирует наблюдения по значению. Линия хранится в ax.lines, коллекция точек scatter появилась бы в ax.collections. Автоматическая сортировка может изменить смысл временного ряда.","verified":"3.14","wrong":["[0, 1, 2]\n0","[2, 0, 1]\n1"]},{"id":"60.4","codeLang":"python","answer":"import matplotlib\nmatplotlib.use('Agg')\nimport matplotlib.pyplot as plt\ndef bar_chart(labels,values):\n    fig,ax=plt.subplots(figsize=(4,3))\n    positions=list(range(len(values)))\n    ax.bar(positions,values)\n    ax.set_xticks(positions,labels)\n    ax.set(title='Сравнение',ylabel='Количество')\n    fig.tight_layout()\n    return fig","answerLang":"python","explanation":"Категориальная ось сопоставляет одинаковые строки одной координате. Для отдельных наблюдений используйте числовые позиции и задайте подписи отдельно. Нулевая высота — настоящий столбец, а не отсутствие записи.","verified":"3.14","check":{"append":"import matplotlib\nmatplotlib.use('Agg')\nimport matplotlib.pyplot as _plt\nimport numpy as _np\nfrom matplotlib.figure import Figure as _Figure\n\nfor labels,values in [(['A','A','B'],[2,0,5]),([],[]),(['0012'],[0])]:\n    before=(labels.copy(),values.copy());fig=bar_chart(labels,values)\n    assert isinstance(fig,_Figure) and len(fig.axes)==1\n    ax=fig.axes[0];assert len(ax.patches)==len(values)\n    assert _np.allclose([p.get_height() for p in ax.patches],values)\n    assert _np.allclose([p.get_x()+p.get_width()/2 for p in ax.patches],range(len(values)))\n    assert [text.get_text() for text in ax.get_xticklabels()]==labels\n    assert ax.get_title()=='Сравнение' and ax.get_ylabel()=='Количество'\n    assert (labels,values)==before;_plt.close(fig)\nprint('OK')","expect":"OK"}},{"id":"60.5","codeLang":"python","answer":"import matplotlib\nmatplotlib.use('Agg')\nimport matplotlib.pyplot as plt\ndef scatter_chart(xs,ys):\n    fig,ax=plt.subplots(figsize=(4,3))\n    ax.scatter(xs,ys,alpha=.7)\n    ax.set(title='Точки',xlabel='X',ylabel='Y')\n    fig.tight_layout()\n    return fig","answerLang":"python","explanation":"Точки подходят для пар наблюдений, когда порядок не означает последовательный путь. Соединение линией добавило бы смысл, которого в данных нет. Повторные координаты остаются повторными наблюдениями.","verified":"3.14","check":{"append":"import matplotlib\nmatplotlib.use('Agg')\nimport matplotlib.pyplot as _plt\nimport numpy as _np\nfrom matplotlib.figure import Figure as _Figure\n\nfor xs,ys in [([2,0,2],[4,0,4]),([],[]),([1],[3])]:\n    before=(xs.copy(),ys.copy());fig=scatter_chart(xs,ys)\n    assert isinstance(fig,_Figure) and len(fig.axes)==1\n    ax=fig.axes[0];assert len(ax.collections)==1 and not ax.lines\n    expected=_np.array(list(zip(xs,ys)),dtype=float).reshape(-1,2)\n    assert _np.allclose(ax.collections[0].get_offsets(),expected)\n    assert ax.get_title()=='Точки' and ax.get_xlabel()=='X' and ax.get_ylabel()=='Y'\n    assert (xs,ys)==before;_plt.close(fig)\nprint('OK')","expect":"OK"}},{"id":"60.6","codeLang":"python","answer":"[2.0, 3.0]\n[0, 2, 4]","answerLang":"text","explanation":"Первый интервал [0,2) содержит 0 и 1; второй [2,4] содержит 2,3,4. Это распределение числовой величины по интервалам, а не отдельный столбец для каждого исходного значения.","verified":"3.14","wrong":["[2.0, 2.0]\n[0, 2, 4]","[3.0, 2.0]\n[0, 2, 4]"]},{"id":"60.7","codeLang":"python","answer":"import matplotlib\nmatplotlib.use('Agg')\nimport matplotlib.pyplot as plt\ndef histogram_chart(values,bins):\n    fig,ax=plt.subplots(figsize=(4,3))\n    ax.hist(values,bins=bins,density=False)\n    ax.set(title='Распределение',xlabel='Значение',ylabel='Частота')\n    fig.tight_layout()\n    return fig","answerLang":"python","explanation":"Число интервалов и их границы определяют представление распределения. Высоты показывают количество наблюдений, а не плотность вероятности. Влияние выбора bins нужно проверять отдельно от красоты рисунка.","verified":"3.14","check":{"append":"import matplotlib\nmatplotlib.use('Agg')\nimport matplotlib.pyplot as _plt\nimport numpy as _np\nfrom matplotlib.figure import Figure as _Figure\n\nfor values,bins in [([0,1,2,3,4],[0,2,4]),([],[0,1,2]),([-2,0,1,8],[0,1,2])]:\n    before=(values.copy(),bins.copy());fig=histogram_chart(values,bins)\n    assert isinstance(fig,_Figure) and len(fig.axes)==1\n    ax=fig.axes[0];counts,_=_np.histogram(values,bins=bins)\n    assert len(ax.patches)==len(bins)-1\n    assert _np.allclose([p.get_height() for p in ax.patches],counts)\n    assert _np.allclose([p.get_x() for p in ax.patches],bins[:-1])\n    assert _np.allclose([p.get_width() for p in ax.patches],_np.diff(bins))\n    assert ax.get_title()=='Распределение' and ax.get_xlabel()=='Значение' and ax.get_ylabel()=='Частота'\n    assert (values,bins)==before;_plt.close(fig)\nprint('OK')","expect":"OK"}},{"id":"60.8","codeLang":"python","answer":"from pathlib import Path\ndef save_plot(fig,path):\n    with Path(path).open('xb') as stream:\n        fig.savefig(stream,format='png',dpi=100)","answerLang":"python","explanation":"savefig не требует окна show. Бинарный режим xb отказывает, если файл уже есть. Переданный файловый объект и format=\"png\" снимают зависимость от расширения временного пути. Ошибка записи может оставить частичный новый файл; атомарность здесь не обещается.","verified":"3.14","check":{"append":"import matplotlib\nmatplotlib.use('Agg')\nimport matplotlib.pyplot as _plt\nimport numpy as _np\nfrom matplotlib.figure import Figure as _Figure\n\nimport tempfile as _tempfile\nfrom pathlib import Path as _Path\nwith _tempfile.TemporaryDirectory() as folder:\n    path=_Path(folder)/'plot.png';fig,ax=_plt.subplots(figsize=(4,3),dpi=72);ax.plot([0,1],[2,0])\n    before=(fig.get_size_inches().copy(),fig.dpi,ax.lines[0].get_ydata().copy())\n    save_plot(fig,path);data=path.read_bytes()\n    assert data.startswith(bytes([137,80,78,71,13,10,26,10])) and int.from_bytes(data[16:20],'big')==400 and int.from_bytes(data[20:24],'big')==300\n    assert _np.array_equal(fig.get_size_inches(),before[0]) and fig.dpi==before[1] and _np.array_equal(ax.lines[0].get_ydata(),before[2])\n    assert _plt.fignum_exists(fig.number)\n    try:save_plot(fig,path)\n    except FileExistsError:pass\n    else:raise AssertionError('Существующий PNG нельзя перезаписывать')\n    assert path.read_bytes()==data;_plt.close(fig)\nprint('OK')","expect":"OK"}},{"id":"60.9","codeLang":"python","answer":"import matplotlib\nmatplotlib.use('Agg')\nimport matplotlib.pyplot as plt\ndef inventory_chart(rows):\n    totals={}\n    for row in rows:totals[row['sku']]=totals.get(row['sku'],0)+row['qty']\n    labels=list(totals);values=list(totals.values());positions=list(range(len(labels)))\n    fig,ax=plt.subplots(figsize=(6,4))\n    bars=ax.bar(positions,values,label='Остаток')\n    ax.set_xticks(positions,labels,rotation=45,ha='right')\n    ax.set(title='Остатки',xlabel='Артикул',ylabel='Количество')\n    ax.set_ylim(bottom=0)\n    ax.bar_label(bars,labels=[str(value) for value in values])\n    fig.tight_layout()\n    return fig","answerLang":"python","explanation":"Сначала строится осмысленная сводка данных, затем график. Порядок словаря сохраняет первое появление кода. Отдельные числовые позиции не объединяют артикулы случайно, нулевой столбец остаётся наблюдением. Подписи и оси объясняют результат без зависимости только от цвета.","verified":"3.14","hint":"Разделите агрегацию и отображение. Проверьте повторный код, настоящий ноль, порядок и подписи сумм.","check":{"append":"import matplotlib\nmatplotlib.use('Agg')\nimport matplotlib.pyplot as _plt\nimport numpy as _np\nfrom matplotlib.figure import Figure as _Figure\n\nfrom copy import deepcopy as _copy\nfor rows,labels,values in [([{'sku':'0012','qty':0},{'sku':'A','qty':2},{'sku':'0012','qty':3},{'sku':'B','qty':0}],['0012','A','B'],[3,2,0]),([],[],[]),([{'sku':'Z','qty':0}],['Z'],[0])]:\n    before=_copy(rows);fig=inventory_chart(rows)\n    assert isinstance(fig,_Figure) and len(fig.axes)==1\n    ax=fig.axes[0];assert len(ax.patches)==len(labels)\n    assert _np.allclose([p.get_height() for p in ax.patches],values)\n    assert _np.allclose([p.get_x()+p.get_width()/2 for p in ax.patches],range(len(labels)))\n    assert [text.get_text() for text in ax.get_xticklabels()]==labels\n    assert [text.get_text() for text in ax.texts]==[str(value) for value in values]\n    assert ax.get_title()=='Остатки' and ax.get_xlabel()=='Артикул' and ax.get_ylabel()=='Количество' and ax.get_ylim()[0]==0\n    assert rows==before;_plt.close(fig)\nfig=inventory_chart([{'sku':'A','qty':2},{'sku':'A','qty':4}])\nassert [p.get_height() for p in fig.axes[0].patches]==[6], 'Повторные количества нужно сложить, а не заменить последним'\n_plt.close(fig)\nprint('OK')","expect":"OK"}},{"id":"60.10","codeLang":"python","answer":"import matplotlib\nmatplotlib.use('Agg')\nimport matplotlib.pyplot as plt\ndef trend_report(days,actual,plan):\n    import numpy as np\n    x=list(range(len(days)))\n    fact=[np.nan if value is None else value for value in actual]\n    target=[np.nan if value is None else value for value in plan]\n    fig,(top,bottom)=plt.subplots(2,1,sharex=True,figsize=(6,5))\n    top.plot(x,fact,marker='o',label='Факт')\n    top.plot(x,target,linestyle='--',label='План')\n    top.set_ylabel('Количество');top.legend()\n    positions=[i for i,(a,p) in enumerate(zip(actual,plan)) if a is not None and p is not None]\n    bottom.bar(positions,[actual[i]-plan[i] for i in positions])\n    bottom.axhline(0,color='black',linewidth=1)\n    bottom.set_xticks(x,days)\n    bottom.set(xlabel='День',ylabel='Отклонение')\n    fig.suptitle('План и факт');fig.tight_layout(rect=(0,0,1,.94))\n    return fig","answerLang":"python","explanation":"Пропуск не означает отсутствие спроса или нулевой результат. NaN сохраняет положение дня и разрывает линию, а отклонение не рассчитывается без обеих сторон. Разные типы линий и подписи различают план/факт без опоры только на цвет. Общая X связывает два представления одних дней, а нулевая линия помогает читать положительное и отрицательное отклонение.","verified":"3.14","hint":"Сохраняйте индекс каждого дня и None как разрыв. Нижняя диаграмма использует только пары измерений; её столбцы остаются на исходных позициях.","check":{"append":"import matplotlib\nmatplotlib.use('Agg')\nimport matplotlib.pyplot as _plt\nimport numpy as _np\nfrom matplotlib.figure import Figure as _Figure\n\nfrom copy import deepcopy as _copy\nfor days,actual,plan in [(['Пн','Вт','Ср','Чт'],[2,None,0,7],[1,3,None,9]),([],[],[]),(['D'],[0],[0]),(['A','B'],[None,None],[1,None])]:\n    before=_copy((days,actual,plan));fig=trend_report(days,actual,plan)\n    assert isinstance(fig,_Figure) and len(fig.axes)==2\n    top,bottom=fig.axes;assert top.get_shared_x_axes().joined(top,bottom)\n    assert len(top.lines)==2 and [line.get_label() for line in top.lines]==['Факт','План']\n    for line,values in zip(top.lines,[actual,plan]):\n        assert _np.array_equal(line.get_xdata(),range(len(days)))\n        assert _np.allclose(_np.asarray(line.get_ydata(),dtype=float),_np.asarray(values,dtype=float),equal_nan=True), 'Не превращайте пропуски в нули'\n    assert top.lines[1].get_linestyle()=='--' and top.get_ylabel()=='Количество' and top.get_legend() is not None\n    positions=[i for i,(a,p) in enumerate(zip(actual,plan)) if a is not None and p is not None]\n    assert len(bottom.patches)==len(positions)\n    assert _np.allclose([p.get_height() for p in bottom.patches],[actual[i]-plan[i] for i in positions])\n    assert _np.allclose([p.get_x()+p.get_width()/2 for p in bottom.patches],positions)\n    assert any(_np.allclose(line.get_ydata(),[0,0]) for line in bottom.lines), 'Нужна нулевая линия'\n    assert bottom.get_xlabel()=='День' and bottom.get_ylabel()=='Отклонение' and [text.get_text() for text in bottom.get_xticklabels()]==days\n    assert fig.get_suptitle()=='План и факт' and (days,actual,plan)==before;_plt.close(fig)\nprint('OK')","expect":"OK"}}]};
